import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        q = int(next(iterator))
        queries = []
        for _ in range(q):
            queries.append(int(next(iterator)))
    except StopIteration:
        return

    # Precompute counts for each possible minimum value
    # Since N is small (<= 50), we can iterate over all subarrays
    count_map = {}

    for i in range(n):
        current_min = a[i]
        for j in range(i, n):
            if j > i:
                if a[j] < current_min:
                    current_min = a[j]

            if current_min not in count_map:
                count_map[current_min] = 0
            count_map[current_min] += 1

    results = []
    for k in queries:
        results.append(str(count_map.get(k, 0)))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
